package com.aicommerce.platform.delivery.application.port;
import java.util.*;
public record ReconciliationNotFound(Optional<String> safeProviderTraceId,NormalizedPlatformEvidence evidence) implements PlatformReconciliationOutcome{public ReconciliationNotFound{safeProviderTraceId=PlatformContractSupport.opt(safeProviderTraceId);PlatformContractSupport.req(evidence);safeProviderTraceId.ifPresent(PlatformContractSupport::safe);if(evidence.attemptKind()!=com.aicommerce.platform.delivery.domain.PlatformAttemptKind.RECONCILE||evidence.resultKind()!=com.aicommerce.platform.delivery.domain.PlatformEvidenceResultKind.NOT_FOUND)throw PlatformContractSupport.invalid();}}
